// ====== Lọc phiếu NHẬP KHO (mua lúa) & dựng dòng cho sổ kế toán ======
// Chạy 1 lần cho tất cả item (runOnceForAllItems)

// 1) Bảng giá: chuẩn hoá để tra theo loại lúa
const priceRows = $('Đọc bảng giá').all().map(i => i.json);
const norm = (s) => String(s || '')
  .toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd').replace(/\s+/g, ' ').trim();
const priceList = priceRows
  .map(r => ({ key: norm(r['Loại hàng / lúa']), gia: Number(String(r['Đơn giá (đ/kg)'] || '').replace(/[^0-9.\-]/g, '')) }))
  .filter(p => p.key);

const lookupPrice = (loai) => {
  const k = norm(loai);
  if (!k) return null;
  let hit = priceList.find(p => p.key === k);
  if (!hit) hit = priceList.find(p => k.includes(p.key) || p.key.includes(k));
  return (hit && !isNaN(hit.gia) && hit.gia > 0) ? hit.gia : null;
};

const toNum = (s) => {
  if (s === null || s === undefined || s === '') return null;
  const n = Number(String(s).replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? null : n;
};

// DD/MM/YYYY -> Date
const parseVNDate = (s) => {
  const m = String(s || '').match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if (!m) return null;
  let [_, d, mo, y] = m; if (y.length === 2) y = '20' + y;
  const dt = new Date(Number(y), Number(mo) - 1, Number(d));
  return isNaN(dt.getTime()) ? null : dt;
};
const fmtDate = (dt) => dt ? `${String(dt.getDate()).padStart(2,'0')}/${String(dt.getMonth()+1).padStart(2,'0')}/${dt.getFullYear()}` : '';

const DUE_DAYS = 30; // hạn thanh toán mặc định (ngày) - đổi nếu cần

const out = [];
let seq = 0;
for (const it of $input.all()) {
  const row = it.json;

  // Bỏ qua dòng đã ghi sổ
  if (String(row['Đã ghi sổ KT'] || '').toUpperCase().includes('C')) continue;

  // Xác định CHIỀU giao dịch theo loại hàng (từ góc nhìn nhà máy Thạnh Hương)
  const loaiHang = row['Loại hàng / lúa'] || '';
  const nl = norm(loaiHang);
  const isByproduct = /(cam|trau|gao|tam)/.test(nl);            // cám/trấu/gạo/tấm = bán ra
  const isPaddy = /(lua|thoc|paddy|nep|om\d|dai thom|st\d|ir\d|khang dan)/.test(nl);
  const kieu = norm(row['Kiểu cân']);
  // Chỉ xử lý MUA LÚA nhập kho
  const isPaddyPurchase = (isPaddy && !isByproduct) || (!isByproduct && !isPaddy && kieu.includes('nhap'));
  if (!isPaddyPurchase) continue;

  seq += 1;
  const sl = toNum(row['TL hàng (kg)']);
  const gia = lookupPrice(loaiHang);
  const thanhTien = (sl !== null && gia !== null) ? Math.round(sl * gia) : '';

  // Số phiếu nhập kho
  const ngayPhieu = row['Ngày phiếu'] || '';
  const dt = parseVNDate(ngayPhieu);
  const compact = dt ? `${dt.getFullYear()}${String(dt.getMonth()+1).padStart(2,'0')}${String(dt.getDate()).padStart(2,'0')}` : new Date().toISOString().slice(0,10).replace(/-/g,'');
  const soPhieuCan = row['Số phiếu'] || '';
  const soPhieuNK = soPhieuCan ? `NK-${String(soPhieuCan).replace(/[^0-9A-Za-z]/g,'')}` : `NK-${compact}-${String(seq).padStart(3,'0')}`;

  // Hạn thanh toán
  const han = dt ? fmtDate(new Date(dt.getTime() + DUE_DAYS*86400000)) : '';

  // Ghi chú & cờ
  const reasons = [];
  const canKiemTra = String(row['Cần kiểm tra'] || '');
  if (canKiemTra.toUpperCase().includes('C')) reasons.push('Phiếu cân cần kiểm tra: ' + (row['Lý do kiểm tra'] || ''));
  if (gia === null) reasons.push('Cần nhập đơn giá (chưa có trong BANG_GIA)');
  const ghiChu = reasons.join('; ');

  const nhaCC = row['Người bán / Khách hàng'] || '';
  const linkAnh = row['Link ảnh'] || '';

  out.push({ json: {
    ngay_nhap: ngayPhieu,
    so_phieu_nk: soPhieuNK,
    loai_nhap: 'Mua lúa nhập kho',
    nha_cung_cap: nhaCC,
    so_chung_tu_goc: soPhieuCan,
    nguoi_giao: row['Người cân'] || '',
    ten_hang: loaiHang || 'Lúa',
    dvt: 'kg',
    sl_thuc_nhap: sl !== null ? sl : '',
    don_gia: gia !== null ? gia : '',
    thanh_tien: thanhTien,
    kcs_chat_luong: row['Ghi chú chất lượng'] || '',
    can_kiem_tra: canKiemTra || 'Không',
    ghi_chu: ghiChu,
    link_anh: linkAnh,
    // ----- công nợ phải trả -----
    cn_loai: 'Phải trả NCC (mua lúa)',
    cn_dien_giai: `Mua ${loaiHang || 'lúa'}${sl!==null?(' '+sl+' kg'):''}${soPhieuCan?(' theo phiếu '+soPhieuCan):''}`,
    cn_gia_tri: thanhTien,
    cn_da_tra: thanhTien === '' ? '' : 0,
    cn_con_no: thanhTien,
    cn_han: han,
    cn_trang_thai: thanhTien === '' ? 'Chờ đơn giá' : 'Chưa trả'
  }});
}

return out;
